"""Human/visual-checked transcription of curated Zhonghua 111–115 questions.
Only question content: no original question numbers, school metadata, scores or solutions.
"""
from pathlib import Path
from collections import Counter
from html import escape
import json
RDIR=Path(__file__).resolve().parent
CAT={x['id']:x for x in json.loads((RDIR/'zhonghua_catalog.json').read_text(encoding='utf8'))}
CUR=[]
for fn in ['curated-zhonghua8.json','curated-zhonghua79.json','curated-zhonghua-extra79.json','curated-zhonghua-earlier.json','curated-zhonghua-completion.json']:
 CUR += [x for x in json.loads((RDIR/fn).read_text(encoding='utf8')) if CAT.get(x.get('paperId'),{}).get('year',0)>=111]
INDEX={(x['paperId'],str(x['number'])):x for x in CUR}
OUT=[]
def T(s):return {'type':'text','text':s}
def O(*items):return {'type':'options','items':list(items)}
def TAB(rows,header=True):return {'type':'table','rows':rows,'header':header}
def SVG(content,w=400,h=250):
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="-10 -10 %s %s" role="img"><g font-family="serif" font-size="15" fill="#111" stroke-linecap="round" stroke-linejoin="round">%s</g></svg>'%(w+20,h+20,content)
def S(svg):return {'type':'svg','svg':svg}
def txt(x,y,s,size=15):return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def line(x1,y1,x2,y2,**kw):return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="#111" stroke-width="1.3" '+ ' '.join(f'{k.replace("_","-")}="{v}"' for k,v in kw.items())+'/>'
def save():
 assert len(OUT)==len({x['id'] for x in OUT})
 (RDIR/'transcribed-zhonghua-late.json').write_text(json.dumps(OUT,ensure_ascii=False,indent=2),encoding='utf8')
 print('Saved',len(OUT),'of',len(CUR),flush=True)
def R(p,n,*blocks):
 q=INDEX[(p,str(n))]
 OUT.append({'id':q['id'],'blocks':[T(b) if isinstance(b,str) else b for b in blocks],'verified':True,'sourceSha256':q['sourceSha256']})

