IDINDEX={q['id']:q for q in CUR}
def G(prefix,key,*blocks):
 q=IDINDEX[f'{prefix}-{key}']
 OUT.append({'id':q['id'],'blocks':[T(b) if isinstance(b,str) else b for b in blocks],'verified':True,'sourceSha256':q['sourceSha256']})
def points(points,segments,labels=None,w=340,h=220,shade=None,extra=''):
 content=''
 if shade:content+='<polygon points="'+' '.join(f'{points[k][0]},{points[k][1]}' for k in shade)+'" fill="#333"/>'
 for a,b in segments:content+=line(*points[a],*points[b])
 for k,(x,y) in points.items():
  content+=f'<circle cx="{x}" cy="{y}" r="1.8"/>'
  dx,dy=(labels or {}).get(k,(-7,-8));content+=txt(x+dx,y+dy,k)
 return SVG(content+extra,w,h)
