def parallels(n=3):
 ys=[45+i*43 for i in range(n)];content=line(85,18,52,ys[-1]+25)+line(148,18,210,ys[-1]+25)
 left=['A','B','C','D'];right=['D','E','F'] if n==3 else ['E','F','G','H']
 for i,y in enumerate(ys):
  x1=85+(52-85)*(y-18)/(ys[-1]+25-18);x2=148+(210-148)*(y-18)/(ys[-1]+25-18)
  content+=line(25,y,260,y)+txt(265,y+5,'L'+str(i+1))+txt(x1-16,y-5,left[i])+txt(x2+5,y-5,right[i])
 content+=txt(45,ys[-1]+44,'M1')+txt(204,ys[-1]+44,'M2')
 return SVG(content,315,ys[-1]+62)
