def intersection(a,b,c,d):
 ax,ay=a;bx,by=b;cx,cy=c;dx,dy=d
 den=(ax-bx)*(cy-dy)-(ay-by)*(cx-dx)
 return (((ax*by-ay*bx)*(cx-dx)-(ax-bx)*(cx*dy-cy*dx))/den,((ax*by-ay*bx)*(cy-dy)-(ay-by)*(cx*dy-cy*dx))/den)
